import AppKit

/// `PasteboardAccess` over the general pasteboard.
///
/// Both our own text write and the restore carry the nspasteboard.org marker types
/// `org.nspasteboard.TransientType` and `org.nspasteboard.AutoGeneratedType` (empty data), so
/// Remora's `ClipboardWatcher` and other clipboard managers do not record either as a new copy.
public struct SystemPasteboardAccess: PasteboardAccess {
    static let markerTypes: [NSPasteboard.PasteboardType] = [
        .init("org.nspasteboard.TransientType"), .init("org.nspasteboard.AutoGeneratedType"),
    ]

    public init() {}

    private var pasteboard: NSPasteboard { .general }

    public var changeCount: Int { pasteboard.changeCount }

    /// Every item with every type's data, in the item's type order (promised data is resolved now).
    public func snapshot() -> PasteboardContents {
        let items = (pasteboard.pasteboardItems ?? []).map { item in
            item.types.compactMap { type in item.data(forType: type).map { PasteboardEntry(type: type.rawValue, data: $0) } }
        }
        return PasteboardContents(items: items)
    }

    public func write(text: String) -> Int {
        let item = NSPasteboardItem()
        item.setString(text, forType: .string)
        Self.mark(item)
        pasteboard.clearContents()
        pasteboard.writeObjects([item])
        return pasteboard.changeCount
    }

    public func restore(_ c: PasteboardContents) -> Int {
        pasteboard.clearContents()
        let items = c.items.map { entries in
            let item = NSPasteboardItem()
            for entry in entries { item.setData(entry.data, forType: .init(entry.type)) }
            Self.mark(item)
            return item
        }
        if !items.isEmpty { pasteboard.writeObjects(items) }
        return pasteboard.changeCount
    }

    private static func mark(_ item: NSPasteboardItem) {
        for type in markerTypes where item.data(forType: type) == nil { item.setData(Data(), forType: type) }
    }
}
